private static String resolveServiceName(XmlContext context, String name) {
    String pkg = context.getMainProject().getPackage();
    if (name.startsWith(".")) {
        return pkg + name;
    } else if (name.indexOf('.') == -1) {
        return pkg + "." + name;
    }
    return name;
}
```

