    public void visitElement(@NonNull XmlContext context, @NonNull Element element) {
        if (TAG_SERVICE.equals(element.getTagName())) {
            String name = resolveServiceName(context, element.getAttributeNS(ANDROID_URI, ATTR_NAME));
            if (name != null) {
                mMediaBrowserServices.put(name, element);
            }
        } else if (TAG_ACTION.equals(element.getTagName())) {
            String actionName = element.getAttributeNS(ANDROID_URI, ATTR_NAME);
            if (ANDROID_MEDIA_ACTION_PLAY_FROM_SEARCH.equals(actionName)) {
                Element parent = getParent(element, TAG_INTENT_FILTER);
                if (parent != null) {
                    Element service = getParent(parent, TAG_SERVICE);
                    if (service != null) {
                        String name = resolveServiceName(context, service.getAttributeNS(ANDROID_URI, ATTR_NAME));
                        if (name != null) {
                            mPlayFromSearchServices.put(name, service);
                            PsiClass cls = mServiceClasses.get(name);
                            if (cls != null && !mReported.contains(name) && !hasOnPlayFromSearch(cls)) {
                                reportMissing(mServiceClassContexts.get(name), cls);
                            }
                        }
                    }
                }
            }
        }
    }

    private static Element getParent(Element element, String tagName) {
        Node parent = element.getParentNode();
        if (parent instanceof Element && tagName.equals(((Element) parent).getTagName())) {
            return (Element) parent;
        }
        return null;
    }

    @Override
    public List<Class<? extends PsiElement>> getApplicableNodeTypes() {
        return Collections.singletonList(PsiClass.class);
    }

    @Override
    public JavaElementVisitor createPsiVisitor(@NonNull JavaContext context) {
        return new JavaElementVisitor() {
            @Override public void visitClass(PsiClass node) {
                String qualifiedName = node.getQualifiedName();
                if (qualifiedName == null) return;
                if (context.getEvaluator().extendsClass(node, ANDROID_MEDIA_BROWSE_MEDIA_BROWSER_SERVICE, false)) {
                    mServiceClasses.put(qualifiedName, node);
                    mServiceClassContexts.put(qualifiedName, context);
                    Element element = mPlayFromSearchServices.get(qualifiedName);
                    if (element != null && !mReported.contains(qualifiedName) && !hasOnPlayFromSearch(node)) {
                        reportMissing(context, node);
                    }
                }
            }
        };
    }

    private boolean hasOnPlayFromSearch(PsiClass cls) {
        for (PsiMethod method : cls.getMethods()) {
            if (ON_PLAY_FROM_SEARCH.equals(method.getName())
                    && method.getParameterList().getParametersCount() == 2
                    && method.getContainingClass() == cls) {
                PsiParameter[] params = method.getParameterList().getParameters();
                if (isString(params[0].getType()) && isBundle(params[1].getType())) {
                    return true;
                }
            }
        }
        return false;
    }

    private static boolean isString(PsiType type) { return "java.lang.String".equals(type.getCanonicalText()); }
    private static boolean isBundle(PsiType type) { return "android.os.Bundle".equals(type.getCanonicalText()); }

    private void reportMissing(@NonNull JavaContext context, @NonNull PsiClass cls) {
        String name = cls.getQualifiedName();
        mReported.add(name);
        context.report(ISSUE, cls, context.getLocation(cls), String.format("Service %1$s should override onPlayFromSearch", name));
    }

