private static String resolveServiceName(@NonNull XmlContext context, @NonNull String name) {
    if (name.isEmpty()) {
        return null;
    }
    String pkg = context.getMainProject().getPackage();
    if (pkg == null || pkg.isEmpty()) {
        return name;
    }
    if (name.startsWith(".")) {
        return pkg + name;
    }
    if (name.indexOf('.') == -1) {
        return pkg + "." + name;
    }
    return name;
}
```

